  /// create a persistent identifier for unauthenticated visitors. This enables
  /// the platform to maintain guest state across page loads and browser
  /// sessions without requiring authentication.
  device_fingerprint String

  /// Timestamp when the guest account was created.
  created_at DateTime @db.Timestamptz

  /// Timestamp when the guest account was last updated.
  updated_at DateTime @db.Timestamptz

  /// Timestamp when the guest account was soft deleted. Null means active.
  deleted_at DateTime? @db.Timestamptz

  //----
  // HAS RELATIONS
  //   - format: (propertyKey targetModel)
  //----
