  /// contextual information such as old/new values, reasons, or additional
  /// attributes. Example: '{"old_status":"draft","new_status":"submitted"}' or
  /// '{"email":"user@example.com"}'.
  details String

  /// Timestamp when the action occurred. Used for chronological ordering and
  /// date range filtering in audit log queries.
  created_at DateTime @db.Timestamptz

  //----
  // BELONGED RELATIONS,
  //   - format: (propertyKey targetModel constraint)
  //----
  organization hrm_platform_organizations @relation(fields: [hrm_platform_organization_id], references: [id], onDelete: Cascade)
  member       hrm_platform_members       @relation(fields: [hrm_platform_member_id], references: [id], onDelete: Cascade)

