    retrievedContract.employee !== undefined,
  );
  TestValidator.predicate(
    "created_at timestamp exists",
    retrievedContract.created_at !== undefined,
  );
  TestValidator.predicate(
    "updated_at timestamp exists",
    retrievedContract.updated_at !== undefined,
  );
}

