  const position = RandomGenerator.name();
  const invitation =
    await api.functional.hrmPlatform.member.employee_invitations.create(
      memberConnection,
      {
        body: {
          email: invitedEmail,
          role_id: role.id,
          employment_type: "full-time",
          expires_at: expiresAtIso,
          position: position,
        } satisfies IHrmPlatformEmployeeInvitation.ICreate,
      },
    );
