      "status is valid",
      ["draft", "submitted", "approved", "rejected"].includes(
        firstTimesheet.status,
      ),
    );
  }
  // 5. Test status filtering with different statuses
  const allStatuses: Array<"draft" | "submitted" | "approved" | "rejected"> = [
