    const employeeRole = await MyGlobal.prisma.hrm_platform_roles.findUnique({
      where: { id: projectMembership.employee.role_id },
      include: {
        rolePermissions: {
          select: {
            permission: {
              select: {
                code: true,
              },
            },
          },
        },
      },
    });
