          parent_task_id: true,
        },
      });
      if (!parentTask) {
        throw new HttpException(
          "Parent task must exist in the same project",
          400,
        );
      }
      if (parentTask.parent_task_id !== null) {
        throw new HttpException(
          "Parent task cannot be a subtask itself (one-level nesting only)",
          400,
        );
      }
