    where: whereInput,
  });
  return {
    pagination: {
      current: page,
      limit: limit,
      records: total,
      pages: Math.ceil(total / limit),
    } satisfies IPage.IPagination,
    data: await ArrayUtil.asyncMap(
      records,
      HrmPlatformTimerAtSummaryTransformer.transform,
    ),
  } satisfies IPageIHrmPlatformTimer.ISummary;
}

