@Controller("/hrmPlatform/member/roles")
export class HrmplatformMemberRolesController {
  /**
   * Create a new custom role within an organization.
   *
   * This endpoint allows organization owners to create custom roles with specific permission combinations. The role is scoped to the organization specified in the request. Custom roles can be edited and deleted (if no employees are assigned) unlike built-in roles.
   *
   * The role name must be unique within the organization. The system automatically sets is_built_in to false for custom roles. Permissions are assigned by providing an array of permission IDs from the available permissions list.
   *
   * @param connection
   * @param body Role creation data including organization ID, role name, optional description, and array of permission IDs to assign to the role.
   * @x-autobe-authorization-type null
   * @x-autobe-authorization-actor member
   * @x-autobe-specification Create a new custom role in the specified organization. Validate that the role name is unique within the organization (check @@unique([organization_id, name]) constraint). Set is_built_in to false for custom roles. Create the role record, then insert permission assignments into hrm_platform_role_permissions junction table for each permission ID provided. Log the role creation in activity log. Return the created role with its assigned permissions. Reject if role name already exists in the organization.
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Post()
  public async create(
    @MemberAuth()
    member: MemberPayload,
    @TypedBody()
    body: IHrmPlatformRole.ICreate,
  ): Promise<IHrmPlatformRole> {
    try {
      return await postHrmPlatformMemberRoles({
        member,
        body,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }

  /**
   * Retrieve a paginated list of roles within the current organization.
   *
   * This endpoint returns all roles defined in the organization, including the three built-in roles (Owner, Manager, Employee) and any custom roles created by organization owners. The list supports filtering by role name and whether the role is built-in or custom.
   *
   * Roles define access control boundaries within an organization. Built-in roles have fixed permission sets and cannot be deleted, while custom roles can be created, edited, and deleted by organization owners when no employees are assigned to them.
   *
   * The response includes role summary information with permission counts. Use the pagination metadata to navigate through large result sets. Filter by is_built_in to distinguish between system-provided and custom roles.
   *
   * @param connection
   * @param body Search criteria for filtering roles including name partial match, built-in flag filter, and pagination parameters for controlling result set size and navigation.
   * @x-autobe-authorization-type null
   * @x-autobe-authorization-actor member
   * @x-autobe-specification Query hrm_platform_roles table filtered by current organization_id from session context. Apply search filters on name (partial match) and is_built_in flag. Support pagination with cursor or offset-based approach. Join with hrm_platform_role_permissions to include permission count in summary. Exclude soft-deleted roles (deleted_at is not null). Return paginated list with total count metadata. Ensure organization data isolation by filtering on organization_id from authenticated session.
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Patch()
  public async index(
    @MemberAuth()
    member: MemberPayload,
    @TypedBody()
    body: IHrmPlatformRole.IRequest,
  ): Promise<IPageIHrmPlatformRole.ISummary> {
    try {
      return await patchHrmPlatformMemberRoles({
        member,
        body,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }

  /**
   * Retrieve a specific role by its unique identifier within the organization context.
   *
   * This endpoint returns the complete role details including the role name, built-in flag, description, and timestamps. Built-in roles (Owner, Manager, Employee) are system-provided and cannot be deleted, while custom roles are created by organization owners with configurable permission sets.
   *
   * The role is scoped to the user's current organization context. Users must have appropriate permissions (employee:view or higher) to access role details. The response includes all role attributes needed for display and permission evaluation.
   *
   * @param connection
   * @param roleId Unique identifier of the role to retrieve (UUID format).
   * @x-autobe-authorization-type null
   * @x-autobe-authorization-actor member
   * @x-autobe-specification Query the hrm_platform_roles table by the provided roleId UUID.
   *
   * Validate that the role exists and belongs to the user's current organization (organization_id matches session context).
   *
   * Return the complete role record including id, organization_id, name, is_built_in, description, created_at, and updated_at fields.
   *
   * Handle 404 error if roleId does not exist or does not belong to the organization.
   *
   * Ensure organization context isolation - users can only access roles within their active organization.
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Get(":roleId")
  public async at(
    @MemberAuth()
    member: MemberPayload,
    @TypedParam("roleId")
    roleId: string & tags.Format<"uuid">,
  ): Promise<IHrmPlatformRole> {
    try {
      return await getHrmPlatformMemberRolesRoleId({
        member,
        roleId,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }

  /**
   * Updates a custom role's name, description, and permission set within the organization.
   *
   * This operation allows organization owners to modify custom roles they have created. The role's name and description can be changed, and the permission set can be completely replaced with a new set of permissions. Built-in roles (Owner, Manager, Employee) cannot be modified and attempts to update them will be rejected.
   *
   * The update operation validates that the new role name is unique within the organization. All permissions in the request must exist in the system's permission master list. The operation replaces the entire permission set - any permissions not included in the request will be removed from the role.
   *
   * @param connection
   * @param roleId UUID identifier of the role to update (scoped to current organization).
   * @param body Update payload containing new role name, optional description, and array of permission IDs to assign to the role.
   * @x-autobe-authorization-type null
   * @x-autobe-authorization-actor member
   * @x-autobe-specification Query hrm_platform_roles by roleId UUID. Validate role exists and belongs to current organization context. Check is_built_in flag - if true, reject with 403 error as built-in roles cannot be modified. For custom roles, validate name uniqueness within organization (check @@unique([organization_id, name]) constraint). Update name and description fields. For permissions, delete existing hrm_platform_role_permissions records and insert new ones based on provided permissionIds array. Validate each permissionId exists in hrm_platform_permissions. Return updated role with permissions. Log activity for role modification.
